import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Probing, Diagnosis and Failure Verdicts","description":"","frontmatter":{"title":"Probing, Diagnosis and Failure Verdicts"},"headers":[],"relativePath":"guide/probe-diagnosis.md","filePath":"guide/probe-diagnosis.md","lastUpdated":1793266312000}`),a={name:`guide/probe-diagnosis.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_5-probing-diagnosis-and-failure-verdicts" tabindex="-1">5. Probing, Diagnosis and Failure Verdicts <a class="header-anchor" href="#_5-probing-diagnosis-and-failure-verdicts" aria-label="Permalink to “5. Probing, Diagnosis and Failure Verdicts”">​</a></h1><h2 id="_5-1-separation-of-probe-and-diagnosis" tabindex="-1">5.1 Separation of Probe and Diagnosis <a class="header-anchor" href="#_5-1-separation-of-probe-and-diagnosis" aria-label="Permalink to “5.1 Separation of Probe and Diagnosis”">​</a></h2><p>The Probe collects facts.</p><p>The Diagnosis judges the cause of failure from multiple facts.</p><p>For example:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Probe A: Wi-Fi connected</span></span>
<span class="line"><span>Probe B: IP address obtained</span></span>
<span class="line"><span>Probe C: default gateway reachable</span></span>
<span class="line"><span>Probe D: public IP unreachable</span></span>
<span class="line"><span>Probe E: proxy local port connectable</span></span>
<span class="line"><span>Probe F: proxy authentication failed</span></span></code></pre></div><p>This evidence must not be naively merged into &quot;network failure&quot;.</p><p>A diagnosis result should include:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Diagnosis</span></span>
<span class="line"><span>├── fault_code</span></span>
<span class="line"><span>├── summary</span></span>
<span class="line"><span>├── confidence (optional)</span></span>
<span class="line"><span>├── evidence_refs[]</span></span>
<span class="line"><span>├── affected_resources[]</span></span>
<span class="line"><span>├── recommended_actions[]</span></span>
<span class="line"><span>└── limitations[]</span></span></code></pre></div><p><code>confidence</code> is an optional rule-based confidence level and must not pretend to be a statistical probability.</p><h2 id="_5-2-failure-types" tabindex="-1">5.2 Failure types <a class="header-anchor" href="#_5-2-failure-types" aria-label="Permalink to “5.2 Failure types”">​</a></h2><p>The first version should distinguish at least:</p><ul><li><code>process_exited</code></li><li><code>service_stopped</code></li><li><code>probe_timeout</code></li><li><code>network_disconnected</code></li><li><code>gateway_unreachable</code></li><li><code>dns_failure</code></li><li><code>proxy_connection_failed</code></li><li><code>proxy_authentication_failed</code></li><li><code>remote_endpoint_unreachable</code></li><li><code>plugin_unavailable</code></li><li><code>dependency_unsatisfied</code></li><li><code>recovery_action_failed</code></li><li><code>verification_failed</code></li><li><code>unknown_failure</code></li></ul><p>Unknown failures must not directly trigger every possible recovery action.</p><h2 id="_5-3-consecutive-failures-and-flapping-suppression" tabindex="-1">5.3 Consecutive failures and flapping suppression <a class="header-anchor" href="#_5-3-consecutive-failures-and-flapping-suppression" aria-label="Permalink to “5.3 Consecutive failures and flapping suppression”">​</a></h2><p>A single timeout must not immediately restart a service.</p><p>Health policies need to support:</p><ul><li>Consecutive failure threshold.</li><li>Consecutive success threshold.</li><li>Probe timeout.</li><li>Failure window.</li><li>Recovery confirmation window.</li><li>Fault cooldown.</li></ul><p>For example:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">health_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10s</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3s</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  failure_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  success_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span></code></pre></div><p>These are example values; actual values should be set per resource type.</p><p>Thresholds only decide whether a fault state is entered; they must not be used to paper over persistent anomalies.</p><h2 id="_5-4-p0-probe-scope" tabindex="-1">5.4 P0 probe scope <a class="header-anchor" href="#_5-4-p0-probe-scope" aria-label="Permalink to “5.4 P0 probe scope”">​</a></h2><p>P0 implements only:</p><ul><li>Process Probe.</li><li>Exec Probe.</li></ul><p>P0 does not implement an HTTP Probe yet.</p><p>The Process Probe checks whether a process exists plus any required process attributes.</p><p>The Exec Probe executes a controlled check command and parses:</p><ul><li>The exit code.</li><li>Standard output.</li><li>Standard error.</li><li>Timeout.</li><li>Startup failure.</li><li>Whether output was truncated.</li></ul><p>The Exec Probe must limit runtime and output size, and clean up the process tree on timeout. On Windows it must not kill only the parent process and leave orphaned children behind.</p><p>Network, HTTP, service management and proxy-specific probes come in later versions.</p><hr>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};